BACKLOG.md:10:## Self-hosted: phone access from anywhere
BACKLOG.md:11:Open Moneo on your phone from any network, like T3 Code, with nothing to install on the phone. Moneo only listens on 127.0.0.1 today, and it signs its owner in automatically, so any remote access must add a login first (an `APP_PASSWORD` sign-in, or Cloudflare Access).
BACKLOG.md:12:- Options weighed: Tailscale Funnel (free, fixed `*.ts.net` URL, nothing on the phone), Cloudflare Tunnel (free tunnel; a fixed URL needs your own domain, about $10/yr), or Tailscale with its phone app (private, no password needed).
BACKLOG.md:13:- HTTPS is required for voice: browsers only give web pages the microphone over a secure connection.
BACKLOG.md:14:- Bank connections from the phone: register the tunnel's `https://…/api/bank/callback` as a second redirect URL in Enable Banking, and send the bank back to whichever address the owner started from (laptop: `https://localhost:3443`).

import { existsSync, readFileSync } from "node:fs";
import { createServer } from "node:https";
import path from "node:path";

// Enable Banking production apps only accept https:// return addresses, and Moneo runs on
// http://localhost. This listener answers on https://localhost:3443 (a certificate trusted only on
// this computer, made by `npm run setup`) and sends the browser straight on to Moneo's callback.
// Nothing is stored here; the code is useless without the app's private key.
export const BANK_RETURN_PORT = 3443;
export const BANK_REDIRECT_URL = `https://localhost:${BANK_RETURN_PORT}/api/bank/callback`;
const CALLBACK = "/api/bank/callback";

export function certificatePaths(dir = path.join(process.cwd(), ".data")) {
  return { key: path.join(dir, "localhost-key.pem"), cert: path.join(dir, "localhost.pem") };
}

/** Where the browser goes next: Moneo's own callback with the bank's query, or nowhere. */
export function forwardTarget(requestUrl: string, appUrl: string) {
  const url = new URL(requestUrl, "https://localhost");
  return url.pathname === CALLBACK ? new URL(`${CALLBACK}${url.search}`, appUrl).toString() : null;
import { createHash, randomBytes } from "node:crypto";
import { z } from "zod";

// Scalable Capital's official MCP server. OAuth 2.1 with dynamic client registration and PKCE
// (public client, no secret); the bearer token then calls MCP tools over Streamable HTTP.
// Hosted redirect URIs must be on Scalable's SaaS allowlist; localhost registers freely.
const ISSUER = "https://mcp.scalable.capital";
export const SCALABLE_MCP_URL = `${ISSUER}/mcp`;
const SCOPE = "openid profile offline_access";
const PROTOCOL_VERSION = "2025-06-18";

export class ScalableError extends Error {
function emailFrom(idToken: string | null) {
  try { return z.object({ email: z.string() }).parse(JSON.parse(Buffer.from(idToken!.split(".")[1], "base64url").toString())).email; }
  catch { return null; }
}

/** The ChatGPT authorize URL. OpenAI only accepts a 127.0.0.1 loopback callback. */
export async function startSignIn(port: number) {
  const state = await load();
  const verifier = randomBytes(32).toString("base64url"), oauthState = randomUUID();
  const redirectUri = `http://127.0.0.1:${port}/api/ai/chatgpt/callback`;
  const clientId = state.account?.clientId ?? "dynamic_agent_client";
  const url = new URL(`${AUTH}/authorize`);
  url.search = new URLSearchParams({
    client_id: clientId, ext_agent_host_id: state.hostId, response_type: "code", redirect_uri: redirectUri, scope: SCOPE, resource: RESOURCE,
    state: oauthState, nonce: randomUUID(), code_challenge_method: "S256", code_challenge: createHash("sha256").update(verifier).digest("base64url"),
    ...(state.account ? { ...(state.account.idToken ? { id_token_hint: state.account.idToken } : {}), ...(state.account.email ? { login_hint: state.account.email } : {}) } : { agent_name_hint: "Moneo" }),
  }).toString();
  await save({ ...state, pending: { state: oauthState, verifier, redirectUri, clientId, createdAt: Date.now() } });
  return url.toString();
}

import { NextResponse } from "next/server";
import { requireWorkspace } from "@/lib/auth";
import { ChatGPTError, finishSignIn } from "@/lib/ai/chatgpt";
import { getEnv } from "@/lib/env";

// ChatGPT redirects here (on 127.0.0.1, as OpenAI requires) after the owner signs in.
export async function GET(request: Request) {
  const back = (result: string) => NextResponse.redirect(new URL(`/settings?chatgpt=${encodeURIComponent(result)}#ai-access`, getEnv().NEXT_PUBLIC_APP_URL), 303);
  try { await requireWorkspace(); } catch { return NextResponse.redirect(new URL("/setup", request.url), 303); }
  try {
    await finishSignIn(new URL(request.url).searchParams);
    return back("connected");
  } catch (error) {
    return back(error instanceof ChatGPTError ? error.message : "ChatGPT sign-in failed. Try again.");
  }
}
